using System.Runtime.CompilerServices;
using MatPlotLibNet.Builders;
using MatPlotLibNet.Fidelity;
using MatPlotLibNet.Indicators;
using MatPlotLibNet.Models;
using MatPlotLibNet.Styling;

namespace MatPlotLibNet.Tests.Fidelity.Charts;

/// <summary>
/// Phase 6 — Financial indicator fidelity tests against pandas_ta reference PNGs.
///
/// The OHLC+volume dataset is generated by a closed-form formula that produces
/// the same values in Python and C#, so unlike the charts drawn from numpy's random generator
/// (whose numbers the generator writes to <c>Fixtures/Matplotlib/data</c>) it needs no data file.
/// Formula: close = 100 + 5·sin(2πi/25) + 3·sin(2πi/7); high/low/open/volume derived.
/// </summary>
public class IndicatorFidelityTests : FidelityTest
{
    private const int N = 60;

    private static (double[] Open, double[] High, double[] Low, double[] Close, double[] Volume) Ohlc(int n = N)
    {
        var open   = new double[n];
        var high   = new double[n];
        var low    = new double[n];
        var close  = new double[n];
        var volume = new double[n];
        for (int i = 0; i < n; i++)
        {
            close[i]  = 100.0 + 5.0 * Math.Sin(2 * Math.PI * i / 25) + 3.0 * Math.Sin(2 * Math.PI * i / 7);
            high[i]   = close[i] + 1.0 + 0.5 * Math.Abs(Math.Sin(i * 0.5));
            low[i]    = close[i] - 1.0 - 0.5 * Math.Abs(Math.Cos(i * 0.5));
            open[i]   = close[i] + 0.3 * Math.Sin(i * 0.7);
            volume[i] = 2500.0 + 1500.0 * Math.Sin(i * 0.3);
        }
        return (open, high, low, close, volume);
    }

    /// <summary>The reference line the generator draws at a level: <c>axhline(level, color=..., linestyle="--", linewidth=0.8)</c>, the
    /// width given in points as matplotlib has it.</summary>
    private static Action<ReferenceLine> DashedAt(Color color) => line =>
    {
        line.Color = color;
        line.LineStyle = LineStyle.Dashed;
        line.LineWidth = 0.8 * RenderDpi / 72;
    };

    /// <summary>The guide lines of an oscillator drawn as the generator draws them: the upper one red, the lower one green, both
    /// <c>linestyle="--", linewidth=0.8</c>.</summary>
    private static void DrawnAsTheReferenceDraws(IndicatorLevels levels)
    {
        levels.UpperColor = Colors.Red;
        levels.LowerColor = Colors.Green;
        levels.LineStyle = LineStyle.Dashed;
        levels.LineWidth = 0.8 * RenderDpi / 72;
    }

    /// <summary>The rows whose picture is one titled pane of an indicator over the high, low and close of the oracle's bars, its X axis
    /// called <c>bar</c> and its legend shown.</summary>
    /// <param name="themeId">The row's theme: <c>classic</c> or <c>v2</c>.</param>
    /// <param name="fixtureName">Name of the reference PNG (without extension).</param>
    /// <param name="title">The title of the pane.</param>
    /// <param name="indicator">Draws the indicator on the axes from the bars.</param>
    /// <param name="callerMember">Automatically resolved caller method name (the row whose limits hold).</param>
    private void AssertHlcPane(string themeId, string fixtureName, string title, Func<AxesBuilder, OhlcvBars, AxesBuilder> indicator,
        [CallerMemberName] string? callerMember = null)
    {
        var (_, high, low, close, _) = Ohlc();
        AssertFidelity(themeId, fixtureName, title, ax => indicator(ax, OhlcvBars.Hlc(high, low, close)).SetXLabel("bar").WithLegend(), callerMember);
    }

    private static double[] BarIndex(int n)
    {
        var x = new double[n];
        for (int i = 0; i < n; i++) x[i] = i;
        return x;
    }

    /// <summary>The close drawn against the bar index with an indicator over it on the same axes, titled, labelled and with its legend as the
    /// generator draws them.</summary>
    private static Figure OverlayFigure(string themeId, string title, double[] close, Func<AxesBuilder, AxesBuilder> indicator) =>
        FidelityFigure(themeId)
            .AddSubPlot(1, 1, 1, ax => indicator(ax.WithTitle(title).Plot(BarIndex(close.Length), close, s => s.Label = "close"))
                .SetXLabel("bar")
                .SetYLabel("price")
                .WithLegend())
            .Build();

    // ─────────────────────────────────────────────────────────────────────────
    // Overlay indicators (price + indicator on same axes)
    // ─────────────────────────────────────────────────────────────────────────

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 14, Ssim = 0.98, DeltaE = 3, V2Rms = 15, V2Ssim = 0.98, V2DeltaE = 4)]   // 2 thin lines; colour distance 0.38 classic, 1.07 v2
    public void Sma_20_MatchesPandasTa(string themeId) =>
        AssertFidelity(OverlayFigure(themeId, "SMA(20) overlay", Ohlc().Close, ax => ax
            .Sma(20, i => i.Label = "SMA(20)")), "ind_sma");

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 14, Ssim = 0.98, DeltaE = 3, V2Rms = 15, V2Ssim = 0.98)]   // same as SMA — thin-line AA diffusion
    public void Ema_20_MatchesPandasTa(string themeId) =>
        AssertFidelity(OverlayFigure(themeId, "EMA(20) overlay", Ohlc().Close, ax => ax
            .Ema(20, i => i.Label = "EMA(20)")), "ind_ema");

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 16, Ssim = 0.96, DeltaE = 3, V2Rms = 29, V2Ssim = 0.76)]   // the reference draws the verb's band: the middle line and the channel filled in its colour; what the pixels read is the band's width: pandas-ta's is sqrt(20/19) = 1.026 times the library's at every bar (it takes the sample standard deviation where Bollinger's definition and TA-Lib take the population's)
    public void BollingerBands_20_2_MatchesPandasTa(string themeId) =>
        AssertFidelity(OverlayFigure(themeId, "Bollinger Bands(20, 2)", Ohlc().Close, ax => ax
            .BollingerBands(20, 2.0)), "ind_bbands");

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 13, Ssim = 0.98, DeltaE = 3, V2Rms = 14)]   // close + VWAP overlay (2 thin lines); colour distance 0.38 classic, 0.63 v2
    public void Vwap_MatchesPandasTa(string themeId)
    {
        var (_, _, _, close, volume) = Ohlc();
        var figure = OverlayFigure(themeId, "VWAP", close, ax => ax
            .Indicator(new Vwap(close, volume) { Label = "VWAP" }));
        AssertFidelity(figure, "ind_vwap");
    }

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 14, Ssim = 0.95, DeltaE = 3, V2Rms = 29, V2Ssim = 0.75)]   // the reference draws the verb's band: the middle line and the channel filled in its colour; what the pixels read is the band's width: pandas-ta's is two times the exponential mean of the true range where the library's is two times Wilder's ATR(20) (TA-Lib's and Keltner's), 0.98 to 1.01 times the library's, and it starts a bar earlier
    public void KeltnerChannels_20_MatchesPandasTa(string themeId)
    {
        var (_, high, low, close, _) = Ohlc();
        var figure = OverlayFigure(themeId, "Keltner Channels(20, 2)", close, ax => ax
            .Indicator(new KeltnerChannels(OhlcvBars.Hlc(high, low, close), 20, 2.0)));
        AssertFidelity(figure, "ind_keltner");
    }

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 18, Ssim = 0.97, DeltaE = 3, V2Rms = 18, V2Ssim = 0.96, V2DeltaE = 3)]   // the five lines at the reference's places and colours; the cloud between the spans is the library's own (classic 17.52 / 0.9660 / 0.76, v2 17.54 / 0.9668 / 2.16 on Windows)
    public void Ichimoku_MatchesPandasTa(string themeId)
    {
        var (_, high, low, close, _) = Ohlc(n: 80);
        var x = BarIndex(80);
        AssertFidelity(themeId, "ind_ichimoku", "Ichimoku Cloud", ax => ax
            .Plot(x, close, s =>   // ax.plot(close, label="close", color="black", linewidth=0.8)
            {
                s.Label = "close";
                s.Color = Colors.Black;
                s.LineWidth = 0.8 * RenderDpi / 72;
            })
            .Indicator(new Ichimoku(OhlcvBars.Hlc(high, low, close), displacement: 25) { LineWidth = 0.8 * RenderDpi / 72 })   // the five lines, linewidth=0.8; pandas-ta shifts the spans and the lagging close by kijun - 1 = 25 bars, the library by the displacement it is given
            .SetXLim(themeId == "classic" ? 0 : -3.95, themeId == "classic" ? 80 : 82.95)   // the reference draws the 80 bars only (its spans end at the last bar), where the library draws the cloud on past them: the limits matplotlib gives bars 0 to 79 (the classic style rounds them to 0 and 80)
            .SetXLabel("bar")
            .SetYLabel("price")
            .WithLegend(legend => legend with { FontSize = 8 * RenderDpi / 72 }));   // ax.legend(fontsize=8)
    }

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 15, Ssim = 0.97, DeltaE = 3, V2Rms = 16, V2Ssim = 0.97, V2DeltaE = 4)]
    public void ParabolicSar_MatchesPandasTa(string themeId)
    {
        var (_, high, low, close, _) = Ohlc();
        var figure = OverlayFigure(themeId, "Parabolic SAR", close, ax => ax
            .ParabolicSar(high, low));
        AssertFidelity(figure, "ind_psar");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Oscillator panels (indicator on its own axes)
    // ─────────────────────────────────────────────────────────────────────────

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 19, Ssim = 0.88, DeltaE = 3, V2Rms = 19, V2Ssim = 0.88, V2DeltaE = 2)]   // the RSI's level lines are the reference's colours (colour distance 0.00 v2, 0.38 classic); the line is Wilder's, seeded by the mean of the first 14 changes as TA-Lib's is, where pandas-ta's adjusted smoothing gives a value from bar 1 and stands up to 25 points from it, 1.5 at bar 59
    public void Rsi_14_MatchesPandasTa(string themeId)
    {
        var (_, _, _, close, _) = Ohlc();
        AssertFidelity(themeId, "ind_rsi", "RSI(14)", ax => ax
            .Rsi(close, 14, i => i.Label = "RSI(14)")
            .AxHLine(70, DashedAt(Colors.Red))      // the overbought and oversold lines and the range of the reference
            .AxHLine(30, DashedAt(Colors.Green))
            .SetYLim(0, 100)
            .SetXLabel("bar")
            .SetYLabel("RSI")
            .WithLegend());
    }

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 23, Ssim = 0.94, DeltaE = 2, V2Rms = 19, V2Ssim = 0.94, V2DeltaE = 2)]   // the parts wear the reference's colours (the histogram the patch cycle's first); the signal is the exponential mean of the line, as pandas-ta's (classic 23.50 / 0.9422 / 0.00, v2 17.18 / 0.9590 / 0.86 on Windows)
    public void Macd_12_26_9_MatchesPandasTa(string themeId)
    {
        var (_, _, _, close, _) = Ohlc();
        AssertFidelity(themeId, "ind_macd", "MACD(12, 26, 9)", ax => ax
            .Indicator(new Macd(close, 12, 26, 9))
            .AxHLine(0, line =>   // ax.axhline(0, color="black", linewidth=0.5)
            {
                line.Color = Colors.Black;
                line.LineStyle = LineStyle.Solid;
                line.LineWidth = 0.5 * RenderDpi / 72;
            })
            .SetXLabel("bar")
            .WithLegend());
    }

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 16, Ssim = 0.96, DeltaE = 3, V2Rms = 13, V2Ssim = 0.98)]   // the slow stochastic of the reference, %D solid (classic 15.83 / 0.9674 / 0.38, v2 12.14 / 0.9891 / 0.42 on Windows)
    public void Stochastic_14_3_MatchesPandasTa(string themeId)
    {
        var (_, high, low, close, _) = Ohlc();
        AssertFidelity(themeId, "ind_stoch", "Stochastic(14, 3)", ax => ax
            .Indicator(new Stochastic(OhlcvBars.Hlc(high, low, close), 14, 3))
            .AxHLine(80, DashedAt(Colors.Red))      // the overbought and oversold lines and the range of the reference
            .AxHLine(20, DashedAt(Colors.Green))
            .SetYLim(0, 100)
            .SetXLabel("bar")
            .WithLegend());
    }

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 28, Ssim = 0.84, DeltaE = 3, V2Rms = 29, V2Ssim = 0.75, V2DeltaE = 2)]   // colour distance 0.51 classic, 0.00 v2; the line is Wilder's, seeded by the mean of the first 14 true ranges as TA-Lib's is, where pandas-ta's adjusted smoothing starts at bar 13 and stands up to 0.058 (1.7 %) from it, 0.003 at bar 59
    public void Atr_14_MatchesPandasTa(string themeId)
    {
        var (_, high, low, close, _) = Ohlc();
        AssertFidelity(themeId, "ind_atr", "Average True Range(14)", ax => ax
            .Indicator(new Atr(OhlcvBars.Hlc(high, low, close), 14) { Label = "ATR(14)" })
            .SetXLabel("bar")
            .SetYLabel("ATR")
            .WithLegend());
    }

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 27, Ssim = 0.77, DeltaE = 3, V2Ssim = 0.77)]   // the lines are the reference's width and colours; the 60 bars drawn are the ones pandas-ta's adjusted rma has not settled over (its ADX stands at 34.4 at bar 28 where Wilder's and TA-Lib's, which the library's are, stand at 10.2), which the pixel scores read (classic 27.52 / 0.7622, v2 26.40 / 0.7783 on Windows)
    public void Adx_14_MatchesPandasTa(string themeId)
        => AssertHlcPane(themeId, "ind_adx", "ADX(14)", (ax, bars) => ax
            .Indicator(new Adx(bars, 14) { Label = "ADX" }));   // ax.plot three times, no colour named: the cycle

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 15, Ssim = 0.97, DeltaE = 3, V2Rms = 16, V2Ssim = 0.97, V2DeltaE = 4)]   // the reference holds the standard formula (see generate.py _standard_cci); v2 16.75 / 0.9854 / 1.43, classic 17.90 / 0.9639 / 0.38 on Windows
    public void Cci_20_MatchesPandasTa(string themeId)
        => AssertHlcPane(themeId, "ind_cci", "Commodity Channel Index(20)", (ax, bars) => ax
            .Cci(bars, 20, i => { i.Label = "CCI(20)"; DrawnAsTheReferenceDraws(i.Levels); }));

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 14, Ssim = 0.98, DeltaE = 3, V2Rms = 14, V2Ssim = 0.98, V2DeltaE = 4)]
    public void WilliamsR_14_MatchesPandasTa(string themeId)
        => AssertHlcPane(themeId, "ind_williamsr", "Williams %R(14)", (ax, bars) => ax
            .WilliamsR(bars, 14, i => { i.Label = "Williams %R(14)"; DrawnAsTheReferenceDraws(i.Levels); }));

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 28, Ssim = 0.87, DeltaE = 3, V2Rms = 30, V2Ssim = 0.81, V2DeltaE = 2)]   // colour distance 0.51 classic, 0.00 v2; the sum starts at the first volume as TA-Lib's does where pandas-ta's starts at the first change, so pandas-ta's whole line stands 2,500 (the first volume) lower
    public void Obv_MatchesPandasTa(string themeId)
    {
        var (_, _, _, close, volume) = Ohlc();
        AssertFidelity(themeId, "ind_obv", "On-Balance Volume", ax => ax
            .Obv(close, volume, i => i.Label = "OBV")
            .SetXLabel("bar")
            .SetYLabel("OBV")
            .WithLegend());
    }
}
